32 \u0438 \u0440\u0430\u0441\u0445\u043E\u0434\u043E\u0432, \u0444\u043E\u0440\u043C\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0435 \u043F\u043B\u0430\u043D-\u0444\u0430\u043A\u0442\u043D\u043E\u0433\u043E \u0430\u043D\u0430\u043B\u0438\u0437\u0430), \xAB\u0423\u0447\u0435\u0442 \u0434\u043E\u0433\u043E\u0432\u043E\u0440\u043E\u0432 \u0438 \u0437\u0430\u0442\u0440\u0430\u0442\xBB (\u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044C \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u043E\u043E\u0431\u043E\u0440\u043E\u0442\u0430 \u043F\u043E \u0434\u043E\u0433\u043E\u0432\u043E\u0440\u0430\u043C \u043A\u043E\u043C\u043F\u0430\u043D\u0438\u0438), \xAB\u041F\u043E\u0434\u0440\u044F\u0434\u0447\u0438\u043A\xBB (\u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u044C  \u0432\u0435\u0434\u0435\u043D\u0438\u044F \u0443\u0447\u0435\u0442\u0430 \u043F\u043E \u0441\u0442\u0440\u043E\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0439 \u0441\u043F\u0435\u0446\u0438\u0444\u0438\u043A\u0435: \u0443\u0447\u0435\u0442 \u041F\u0411\u0423 2/2008, \u0444\u043E\u0440\u043C\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0435 \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u043E\u0432 \u041A\u0421-2, \u041A\u0421-3, \u041A\u0421-6, \u0443\u0447\u0435\u0442 \u043D\u0435\u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u043D\u043E\u0433\u043E \u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u0441\u0442\u0432\u0430, \u0443\u0447\u0435\u0442 \u0433\u0430\u0440\u0430\u043D\u0442\u0438\u0439\u043D\u044B\u0445 \u0443\u0434\u0435\u0440\u0436\u0430\u043D\u0438\u0439 \u0438 \u043C\u043D\u043E\u0433\u043E\u0435 \u0434\u0440\u0443\u0433\u043E\u0435). \u0438 \xAB\u0421\u043D\u0430\u0431\u0436\u0435\u043D\u0438\u0435 \u0438 \u0441\u043A\u043B\u0430\u0434\xBB (\u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044C \u0441\u0442\u0440\u043E\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u043C\u0430\u0442\u0435\u0440\u0438\u0430\u043B\u043E\u0432 \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u